import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { CodexChat, CodexEntry, Sandbox } from '../types'
import { firstRow, rowsFor, unwrap, wrap } from './field'

const TOOL_NAME = 'falar'
const TOOL = `mcp__codex-chat__${TOOL_NAME}`
const PANE = 'codex-chat'
const COMMAND = 'codex-chat'
const LIMITE = 8
const KEEP = 200
const SHOWN = 30

const CHAT = { plugin: 'codex-chat', key: 'chat' } as const
const FRESH: CodexChat = {
  sandbox: 'read-only',
  entradas: [],
  isBusy: false,
  trocas: 0,
  limite: LIMITE,
  runs: 0,
  rascunho: '',
}
const chat = atom(CHAT, FRESH)

type Engine = EngineInterface
type Turn = { isOk: true; resposta: string; comandos: string[] } | { isOk: false; erro: string }

const INSTRUCTIONS = `# Conversa com o Codex (codex-chat)

A ferramenta ${TOOL} manda uma mensagem ao Codex (o agente de código da OpenAI, rodando nesta mesma pasta) e devolve a resposta dele. A conversa continua entre as chamadas: o Codex lembra das mensagens anteriores até começar uma conversa nova (\`novaConversa: true\`). O usuário acompanha tudo num painel e também pode falar com o Codex por lá; o que ele disser chega a você junto com a próxima resposta.

Use quando o usuário pedir para consultar, discutir, revisar ou decidir algo junto com o Codex. Escreva ao Codex como a outro engenheiro: o contexto, o que você quer dele e o formato da resposta. Continue a troca enquanto houver divergência a resolver e pare quando convergirem; há um limite de trocas por conversa, que só o usuário libera. Por padrão o Codex só lê os arquivos; use \`sandbox: "workspace-write"\` apenas quando o usuário quiser que o Codex edite. A resposta do Codex é a opinião de outro agente: avalie antes de seguir, e ao final conte ao usuário o que vocês concluíram.`

const OPENING =
  'Você está numa conversa com o Claude, outro agente de código, que roda no Claude Code nesta mesma pasta. ' +
  'O usuário acompanha a conversa num painel e às vezes fala com você direto. Cada mensagem começa com ' +
  '[Claude] ou [Usuário]: responda a quem falou, de forma direta e concisa, e discorde quando for o caso.\n\n'

const SCHEMA = {
  type: 'object',
  properties: {
    mensagem: { type: 'string', description: 'O que dizer ao Codex.' },
    sandbox: {
      type: 'string',
      enum: ['read-only', 'workspace-write'],
      description: 'read-only (padrão): o Codex só lê. workspace-write: pode editar arquivos da pasta.',
    },
    novaConversa: {
      type: 'boolean',
      description: 'true começa uma conversa nova com o Codex, sem o histórico anterior.',
    },
  },
  required: ['mensagem'],
}

// The running Codex, so the pane's Parar can end it; `return()` kills the child.
let running: AsyncGenerator<unknown, unknown> | undefined
let isStopped = false

// The pane follows the conversation's end until the person scrolls up, and
// again once they scroll back to the end.
let isFollowing = true
let pendingScroll: { cancel: () => void } | undefined

const TICK = 500
const SPINNER = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏']

const duration = (ms: number) => {
  const seconds = Math.max(0, Math.round(ms / 1000))
  return seconds < 60 ? `${seconds}s` : `${Math.floor(seconds / 60)}min ${String(seconds % 60).padStart(2, '0')}s`
}

const tokens = (n: number) => (n < 1000 ? `${n}` : `${(n / 1000).toFixed(n < 10_000 ? 1 : 0).replace('.', ',')}k`)

// The model and effort set at the top of the config.toml Codex reads, once a
// session: $CODEX_HOME's when set (a profile of its own), else ~/.codex's.
let modelo: string | undefined
const readModel = async ($: Engine) => {
  const home = await $.env.get('HOME')
  const dir = (await $.env.get('CODEX_HOME')) || (home ? `${home}/.codex` : undefined)
  if (!dir) return undefined
  const text = await $.fs.read(`${dir}/config.toml`).catch(() => '')
  const top = String(text).split(/^\s*\[/m)[0] ?? ''
  const value = (key: string) => new RegExp(`^\\s*${key}\\s*=\\s*"([^"]+)"`, 'm').exec(top)?.[1]
  const name = value('model')
  const effort = value('model_reasoning_effort')
  return name && effort ? `${name} (${effort})` : name
}

const sandboxOf = (value: unknown): Sandbox => (value === 'workspace-write' ? 'workspace-write' : 'read-only')

// Codex runs each command as `/usr/bin/zsh -lc <command>`: show the command alone.
const commandText = (command: string) => command.replace(/^\S*sh -lc /, '').replace(/^'(.*)'$/s, '$1')

// After the redraw the write asked for (thirty a second at most), so `end` is the new end.
const follow = ($: Engine) => {
  if (!isFollowing) return
  pendingScroll?.cancel()
  pendingScroll = $.clock.after(80, () => {
    pendingScroll = undefined
    void $.ui.scroll({ in: PANE, to: 'end' }).catch(() => undefined)
  })
}

const add = async ($: Engine, entry: CodexEntry) => {
  await update($, chat, c => ({ ...c, entradas: [...c.entradas, entry].slice(-KEEP) }))
  follow($)
}

const change = async ($: Engine, id: string, patch: Partial<CodexEntry>) => {
  await update($, chat, c => ({
    ...c,
    entradas: c.entradas.map(one => (one.id === id ? { ...one, ...patch } : one)),
  }))
  follow($)
}

const untold = (c: CodexChat) =>
  c.entradas.filter(one => one.isPainel && !one.isTold && (one.de === 'usuario' || one.de === 'codex'))

const markTold = ($: Engine) =>
  update($, chat, c => ({ ...c, entradas: c.entradas.map(one => (one.isPainel ? { ...one, isTold: true } : one)) }))

const transcript = (entries: CodexEntry[]) =>
  entries.map(one => `${one.de === 'usuario' ? 'Usuário' : 'Codex'}: ${one.texto}`).join('\n\n')

// One Codex turn: `codex exec` for the first message, `codex exec resume` after,
// the message on stdin. Each event lands in the pane as it comes.
const runCodex = async (
  $: Engine,
  de: 'claude' | 'usuario',
  mensagem: string,
  sandbox: Sandbox,
  signal?: AbortSignal,
): Promise<Turn> => {
  const start = await read($, chat)
  const run = start.runs + 1
  const isPainel = de === 'usuario'
  isStopped = false
  if (isPainel) isFollowing = true
  const startedAt = await $.clock.now()
  // Redraws the elapsed time and the spinner while Codex works.
  const ticker = $.clock.every(TICK, () => $.ui.invalidate('ui.render'))
  await update($, chat, c => ({
    ...c,
    isBusy: true,
    startedAt,
    runs: run,
    entradas: [...c.entradas, { id: `${run}:in`, de, texto: mensagem, isPainel }].slice(-KEEP),
  }))
  follow($)

  const config = ['--json', '--skip-git-repo-check', '-c', `sandbox_mode="${sandbox}"`]
  const argv = start.threadId
    ? ['codex', 'exec', 'resume', ...config, start.threadId, '-']
    : ['codex', 'exec', ...config, '-']
  const input = `${start.threadId ? '' : OPENING}[${de === 'claude' ? 'Claude' : 'Usuário'}]: ${mensagem}`

  const respostas: string[] = []
  const comandos: string[] = []
  let falha = ''
  let stderr = ''
  let buffer = ''

  const handle = async (line: string) => {
    let event: any
    try {
      event = JSON.parse(line)
    } catch {
      return
    }
    const item = event?.item
    const id = `${run}:${item?.id}`
    if (event?.type === 'thread.started') {
      await update($, chat, c => ({ ...c, threadId: String(event.thread_id) }))
    } else if (event?.type === 'item.started' && item?.type === 'command_execution') {
      await add($, { id, de: 'comando', texto: commandText(String(item.command)), isRunning: true, isPainel })
    } else if (event?.type === 'item.completed' && item?.type === 'command_execution') {
      const texto = commandText(String(item.command))
      comandos.push(texto)
      const current = await read($, chat)
      if (current.entradas.some(one => one.id === id)) await change($, id, { isRunning: false, exitCode: item.exit_code })
      else await add($, { id, de: 'comando', texto, exitCode: item.exit_code, isPainel })
    } else if (event?.type === 'item.completed' && item?.type === 'agent_message') {
      const texto = String(item.text ?? '').trim()
      if (texto === '') return
      respostas.push(texto)
      await add($, { id, de: 'codex', texto, isPainel })
    } else if (event?.type === 'turn.completed') {
      const lido = Number(event.usage?.input_tokens)
      if (Number.isFinite(lido) && lido > 0) await update($, chat, c => ({ ...c, contexto: lido }))
    } else if (event?.type === 'turn.failed') {
      falha = String(event.error?.message ?? 'o turno falhou')
    } else if (event?.type === 'error') {
      falha = String(event.message ?? 'erro')
    }
  }

  const stream = $.process.spawn({ argv, input })
  running = stream
  const stop = () => void stream.return(undefined as never).catch(() => undefined)
  signal?.addEventListener('abort', stop)
  let code: number | null = null
  try {
    for await (const { stream: pipe, text } of stream) {
      if (pipe === 'stderr') {
        stderr = (stderr + text).slice(-4000)
        continue
      }
      const lines = (buffer + text).split('\n')
      buffer = lines.pop() ?? ''
      for (const line of lines) await handle(line)
    }
    if (buffer.trim()) await handle(buffer)
    code = (await stream.result).code
  } catch (error) {
    if (!isStopped && !signal?.aborted) falha ||= `não consegui rodar o Codex (${String(error)})`
  } finally {
    signal?.removeEventListener('abort', stop)
    ticker.cancel()
    running = undefined
    await update($, chat, c => ({
      ...c,
      isBusy: false,
      startedAt: undefined,
      entradas: c.entradas.map(one => (one.isRunning ? { ...one, isRunning: false } : one)),
    }))
    follow($)
  }

  if (isStopped || signal?.aborted) falha = 'interrompido antes de terminar'
  else if (respostas.length === 0 && !falha) {
    const tail = stderr.split('\n').filter(line => line.trim() && !/^\S+Z\s+(WARN|ERROR) /.test(line)).slice(-3)
    falha = `o Codex saiu sem responder (código ${code})${tail.length ? `: ${tail.join(' ')}` : ''}`
  }
  if (falha) {
    await add($, { id: `${run}:erro`, de: 'erro', texto: falha, isPainel })
    if (respostas.length === 0) return { isOk: false, erro: falha }
  }
  const took = duration((await $.clock.now()) - startedAt)
  const ran = comandos.length === 1 ? '1 comando' : `${comandos.length} comandos`
  await add($, { id: `${run}:fim`, de: 'fim', texto: comandos.length ? `${took} · ${ran}` : took, isPainel })

  return { isOk: true, resposta: respostas.join('\n\n'), comandos }
}

const say = async ($: Engine, texto: string) => {
  const c = await read($, chat)
  const mensagem = texto.trim()
  if (mensagem === '' || c.isBusy) return
  await update($, chat, cur => ({ ...cur, rascunho: '' }))
  await runCodex($, 'usuario', mensagem, c.sandbox)
}

const tellClaude = async ($: Engine) => {
  const entries = untold(await read($, chat))
  if (entries.length === 0) return
  await markTold($)
  await $.prompt.submit({
    text: `Conversei com o Codex no painel do codex-chat:\n\n${transcript(entries)}`,
    asUser: true,
  })
}

const stopCodex = () => {
  isStopped = true
  void running?.return(undefined).catch(() => undefined)
}

// The field grows with the text from ROWS to MAX_ROWS rows, then scrolls within.
const ROWS = 3
const MAX_ROWS = 12

// The dock paints panes with the theme's sidebar gray; a dark theme gets carbon
// instead, a light one keeps the theme's own.
const CARBON = '#161616'
const paneBackground = async ($: Engine): Promise<string | undefined> => {
  const rows = await $.config.list().catch(() => [])
  const theme = String(rows.find(row => row.key === 'theme')?.value ?? '')
  return theme.startsWith('light') ? undefined : CARBON
}

// Opened by a tool call, the pane must not take the keyboard from the prompt.
const openPane = ($: Engine, isAsked = false) =>
  $.ui.open({ id: PANE, title: 'Codex', rows: 24, ...(isAsked ? { focus: true as const } : {}) })

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    // A reload kills a Codex that was running; the state outlives it, so say so.
    await update($, chat, c => {
      const was = { ...FRESH, ...c }
      const entradas = was.entradas.map(one => (one.isRunning ? { ...one, isRunning: false } : one))
      const cut: CodexEntry = { id: `${was.runs}:erro`, de: 'erro', texto: 'interrompido: o mod recarregou no meio da resposta' }
      return {
        ...was,
        isBusy: false,
        startedAt: undefined,
        entradas: was.isBusy ? [...entradas, cut].slice(-KEEP) : entradas,
      }
    })
    await $.tool.register({
      name: TOOL_NAME,
      description:
        'Manda uma mensagem ao Codex (agente de código da OpenAI, nesta pasta) e devolve a resposta dele. ' +
        'A conversa continua entre as chamadas. Use para consultar, discutir ou revisar algo junto com o Codex.',
      inputSchema: SCHEMA,
      isDeferred: false,
    })
    await $.command.register({ name: COMMAND, description: 'Abre o painel da conversa com o Codex' })
    modelo = await readModel($).catch(() => undefined)

    return next(e)
  })

  on('prompt.compose', async ($, e, next) => {
    const composed = await next(e)
    if (!e.tools.includes(TOOL)) return composed

    return {
      sections: [...composed.sections, { id: 'codex-chat:instructions', text: INSTRUCTIONS, scope: 'session' }],
    }
  })

  // Reading is the default and needs no prompt; letting Codex edit asks as any tool would.
  on('tool.check', { tool: 'mcp__codex-chat__falar' }, async ($, e, next) => {
    const verdict = await next(e)
    if (verdict.decision !== 'ask' || e.ceiling === 'ask') return verdict
    if (sandboxOf((e.input as { sandbox?: unknown })?.sandbox) !== 'read-only') return verdict

    return { ...verdict, decision: 'allow', reason: 'codex-chat: o Codex só lê os arquivos' }
  })

  on('tool.call', { tool: 'mcp__codex-chat__falar' }, async ($, e, next) => {
    const input = e as { mensagem?: unknown; sandbox?: unknown; novaConversa?: unknown }
    const mensagem = String(input.mensagem ?? '').trim()
    if (mensagem === '') return { deny: 'codex-chat: informe a `mensagem` para o Codex.' }
    if (input.novaConversa === true) {
      await update($, chat, c => (c.isBusy ? c : { ...c, threadId: undefined, trocas: 0, limite: LIMITE }))
    }

    const c = await read($, chat)
    if (c.isBusy) {
      return { deny: 'codex-chat: o Codex ainda está respondendo outra mensagem (talvez do usuário, no painel). Tente de novo em seguida.' }
    }
    if (c.trocas >= c.limite) {
      return {
        deny:
          `codex-chat: a conversa chegou ao limite de ${c.limite} mensagens suas ao Codex. ` +
          `Pare aqui e resuma ao usuário o que vocês concluíram; ele pode liberar mais trocas no painel (/${COMMAND}).`,
      }
    }

    const heard = untold(c)
    await update($, chat, cur => ({ ...cur, trocas: cur.trocas + 1 }))
    void openPane($).catch(() => undefined)
    const turn = await runCodex($, 'claude', mensagem, sandboxOf(input.sandbox), next.signal)
    if (heard.length > 0) await markTold($)
    if (!turn.isOk) return { deny: `codex-chat: ${turn.erro}` }

    const after = await read($, chat)
    const before = heard.length
      ? `Antes da sua mensagem, o usuário conversou com o Codex no painel:\n\n${transcript(heard)}\n\n---\n\n`
      : ''
    const comandos = turn.comandos.length
      ? `\n\nComandos que o Codex rodou: ${turn.comandos.slice(0, 12).map(one => `\`${one}\``).join(', ')}`
      : ''

    return {
      result:
        `${before}Resposta do Codex:\n\n${turn.resposta}${comandos}\n\n` +
        `(mensagem ${after.trocas} de ${after.limite} nesta conversa; sandbox ${sandboxOf(input.sandbox)})`,
    }
  })

  on('ui.scroll', { component: 'Pane', requestId: PANE }, async ($, e, next) => {
    const moved = await next(e)
    if (e.origin.kind === 'person') {
      isFollowing = e.offset >= e.contentRows - e.bodyRows
      if (!isFollowing) pendingScroll?.cancel()
    }

    return moved
  })

  on('command.run', { command: 'codex-chat' }, async $ => {
    await openPane($, true)

    return { text: 'Painel do Codex aberto.' }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const ui = $.ui.resolve(e)
    const { Box, Text, Button, Markdown } = ui
    const Input = 'Input' in ui ? ui.Input : undefined
    const c = await read($, chat)
    const now = await $.clock.now()
    const pending = untold(c).length
    const backgroundColor = await paneBackground($)
    // The field between two rules, as the prompt box draws its own.
    const ruleWidth = Math.max(1, e.props.bodyColumns - 2)
    const rule = c.isBusy ? 'subtle' : 'promptBorder'
    const elapsed = c.startedAt === undefined ? '' : duration(now - c.startedAt)
    const spinner = SPINNER[Math.floor(now / TICK) % SPINNER.length] ?? '⠋'
    const isAtLimit = c.trocas >= c.limite
    // The field is the rule's width less "❯ "; the draft is kept plain and drawn wrapped.
    const fieldWidth = ruleWidth - 2
    const wrapOf = (plain: string) => wrap(plain, firstRow(fieldWidth, 'enviar'), fieldWidth - 1)
    const draft = wrapOf(c.rascunho)

    // A row hung under a Codex turn, as the transcript hangs a tool's output: ⎿, a mark, the text.
    const hung = (key: string, mark: string, color: string | undefined, text: string, isCut = false) => (
      <Box key={key} flexDirection="row" paddingLeft={2}>
        <Text dimColor>{'⎿ '}</Text>
        <Text color={color} dimColor={!color}>{`${mark} `}</Text>
        <Text dimColor wrap={isCut ? 'truncate-end' : 'wrap'}>
          {text}
        </Text>
      </Box>
    )

    const line = (one: CodexEntry) => {
      if (one.de === 'comando') {
        const mark = one.isRunning ? spinner : one.exitCode === 0 ? '✓' : '✗'
        const color = one.isRunning ? 'warning' : one.exitCode === 0 ? 'success' : 'error'
        return hung(one.id, mark, color, `$ ${one.texto}`, true)
      }
      if (one.de === 'fim') return hung(one.id, '◷', undefined, one.texto)
      if (one.de === 'erro') {
        return (
          <Box key={one.id} flexDirection="row" paddingLeft={2}>
            <Text dimColor>{'⎿ '}</Text>
            <Text color="error">{`✗ ${one.texto}`}</Text>
          </Box>
        )
      }
      const head =
        one.de === 'claude'
          ? { glyph: '✻', who: 'Claude', color: 'claude', to: ' → Codex' }
          : one.de === 'usuario'
            ? { glyph: '●', who: 'Você', color: 'suggestion', to: ' → Codex' }
            : { glyph: '◆', who: 'Codex', color: 'success', to: '' }

      return (
        <Box key={one.id} flexDirection="column" marginTop={1}>
          <Box flexDirection="row">
            <Text color={head.color} bold>{`${head.glyph} ${head.who}`}</Text>
            {head.to && <Text dimColor>{head.to}</Text>}
          </Box>
          <Box paddingLeft={2}>
            {one.de === 'codex' ? <Markdown text={one.texto} /> : <Text>{one.texto}</Text>}
          </Box>
        </Box>
      )
    }

    // The facts of the conversation, under the field as the prompt's footer sits under it.
    const facts = [
      { key: 'trocas', text: `Claude ${c.trocas}/${c.limite}`, color: isAtLimit ? 'warning' : undefined },
      {
        key: 'sandbox',
        text: c.sandbox === 'read-only' ? 'só leitura' : 'pode editar',
        color: c.sandbox === 'read-only' ? undefined : 'warning',
      },
      ...(modelo ? [{ key: 'modelo', text: modelo, color: undefined }] : []),
      ...(c.contexto ? [{ key: 'contexto', text: `contexto ${tokens(c.contexto)}`, color: undefined }] : []),
      ...(c.threadId ? [{ key: 'sessao', text: `sessão ${c.threadId.slice(0, 8)}`, color: undefined }] : []),
    ]

    return (
      <Box
        flexDirection="column"
        backgroundColor={backgroundColor}
        width={e.props.bodyColumns}
        minHeight={e.props.placement === 'dock' ? e.props.scroll.bodyRows : undefined}
        paddingX={1}
      >
        {c.entradas.length === 0 && (
          <Box flexDirection="column" marginTop={1}>
            <Text color="success" bold>
              ◆ O Codex está pronto nesta pasta
            </Text>
            <Box paddingLeft={2} flexDirection="column">
              <Text dimColor>Peça ao Claude algo como “discute com o Codex o plano de cache”,</Text>
              <Text dimColor>ou escreva abaixo para falar com o Codex direto.</Text>
            </Box>
          </Box>
        )}
        {c.entradas.length > SHOWN && <Text dimColor>{`… ${c.entradas.length - SHOWN} anteriores`}</Text>}
        {c.entradas.slice(-SHOWN).map(line)}
        {c.isBusy && (
          <Box key="working" marginTop={1} paddingLeft={2}>
            <Text color="warning">{`${spinner} Codex trabalhando… ${elapsed}`}</Text>
          </Box>
        )}

        {Input ? (
          <Box flexDirection="column" marginTop={1}>
            <Box flexDirection="row" columnGap={2} flexWrap="wrap">
              <Text color="suggestion" bold>
                Falar com o Codex
              </Text>
              <Text dimColor>Ctrl+J quebra a linha</Text>
            </Box>
            <Text color={rule}>{'─'.repeat(ruleWidth)}</Text>
            <Box flexDirection="row">
              <Box width={2} flexShrink={0}>
                <Text color={c.isBusy ? 'subtle' : 'suggestion'}>❯</Text>
              </Box>
              <Input
                key="mensagem"
                autoFocus
                rows={rowsFor(draft, ROWS, MAX_ROWS)}
                placeholder={c.isBusy ? 'espere o Codex terminar' : 'sua mensagem ao Codex'}
                value={draft.text}
                submitLabel="enviar"
                onInput={value => update($, chat, cur => ({ ...cur, rascunho: unwrap(wrapOf(cur.rascunho), value) }))}
                onSubmit={async value => {
                  const cur = await read($, chat)
                  void say($, unwrap(wrapOf(cur.rascunho), value))
                }}
              />
            </Box>
            <Text color={rule}>{'─'.repeat(ruleWidth)}</Text>
          </Box>
        ) : (
          <Box marginTop={1}>
            <Text dimColor>Mensagens ao Codex só podem ser digitadas no terminal ou no desktop.</Text>
          </Box>
        )}

        <Box key="footer" flexDirection="row" flexWrap="wrap" paddingLeft={2}>
          {c.isBusy ? (
            <Text color="warning">{`${spinner} respondendo ${elapsed}`}</Text>
          ) : (
            <Text color="success">○ pronto</Text>
          )}
          {facts.map(fact => (
            <Box key={`fact-${fact.key}`} flexDirection="row">
              <Text dimColor>{'  ·  '}</Text>
              <Text color={fact.color} dimColor={!fact.color}>
                {fact.text}
              </Text>
            </Box>
          ))}
        </Box>

        <Box flexDirection="row" gap={2} flexWrap="wrap" marginTop={1}>
          {c.isBusy && (
            <Button key="stop" onPress={stopCodex}>
              Parar
            </Button>
          )}
          {pending > 0 && !c.isBusy && (
            <Button key="tell" variant="primary" onPress={() => tellClaude($)}>
              {`Contar ao Claude (${pending})`}
            </Button>
          )}
          {c.trocas >= c.limite && (
            <Button key="release" onPress={() => update($, chat, cur => ({ ...cur, limite: cur.limite + LIMITE }))}>
              {`Liberar +${LIMITE} mensagens`}
            </Button>
          )}
          <Button
            key="sandbox"
            onPress={() =>
              update($, chat, cur => ({
                ...cur,
                sandbox: sandboxOf(cur.sandbox === 'read-only' ? 'workspace-write' : 'read-only'),
              }))
            }
          >
            {c.sandbox === 'read-only' ? 'Deixar o Codex editar' : 'Voltar a só leitura'}
          </Button>
          {!c.isBusy && (
            <Button
              key="new"
              dimColor
              onPress={() => update($, chat, cur => ({ ...FRESH, sandbox: cur.sandbox }))}
            >
              Nova conversa
            </Button>
          )}
          <Button key="close" role="dismiss" dimColor onPress={() => $.ui.close({ id: PANE })}>
            Fechar
          </Button>
        </Box>
      </Box>
    )
  })
}

