export type Sandbox = 'read-only' | 'workspace-write'

export type CodexEntry = {
  id: string
  // `fim` closes a Codex turn: how long it took and what it ran.
  de: 'claude' | 'usuario' | 'codex' | 'comando' | 'erro' | 'fim'
  texto: string
  // A command still running; its exit code once done.
  isRunning?: boolean
  exitCode?: number | null
  // Said in the pane, by the person or by Codex answering them; told once Claude has read it.
  isPainel?: boolean
  isTold?: boolean
}

export type CodexChat = {
  threadId?: string
  sandbox: Sandbox
  entradas: CodexEntry[]
  isBusy: boolean
  // When the running turn started, for the elapsed time while it runs.
  startedAt?: number
  // Tokens Codex read on its last turn: the conversation's size so far.
  contexto?: number
  // Claude's messages in this conversation, and how many it may send before the person releases more.
  trocas: number
  limite: number
  runs: number
  rascunho: string
}

declare module 'claude-code' {
  interface PluginState {
    'codex-chat': { chat: CodexChat }
  }
